class LibraryMemberBean { private String membershipId; private String name; private boolean premiumMember; private String storedAnswer;
 public LibraryMemberBean(){this(null,null);} public LibraryMemberBean(String name){this(null,name);} public LibraryMemberBean(String id,String name){membershipId=id;this.name=name;}
 public String getMembershipId(){return membershipId;} public void setMembershipId(String id){if(membershipId==null)membershipId=id;} public String getName(){return name;} public void setName(String n){name=n;} public boolean isPremiumMember(){return premiumMember;} public void setPremiumMember(boolean p){premiumMember=p;} public void setSecurityAnswer(String a){storedAnswer=a==null?null:Integer.toHexString(a.hashCode());}
}
public class Problem4{public static void main(String[]x){LibraryMemberBean m=new LibraryMemberBean();m.setMembershipId("LIB-8841");m.setMembershipId("FAKE-0000");System.out.println(m.getMembershipId());System.out.println(new LibraryMemberBean("Priya Nair").getMembershipId());System.out.println(new LibraryMemberBean("LIB-8841","Priya Nair").getMembershipId());}}
